import type { Snapshot } from '../../src/snapshot';
import type { Hex, SignedTxView, Verdict, WalletView } from '../../src/types';
import { txHashOf } from './encode';
import { OTHER_KEY, signedTxWithKey, TEST_KEY, TEST_KEY_ADDRESS } from './signing';

export const SYNTHETIC_NOTE =
  'Hand-made for tests (generated by test/fixtures/generate.ts). NOT chain data.';

/** Address of the throwaway test key 0x...01 (see helpers/signing.ts). Fixture txs are really signed by it. */
export const SYNTHETIC_ADDRESS: Hex = TEST_KEY_ADDRESS;
export const SYNTHETIC_RECIPIENT: Hex = '0x2222222222222222222222222222222222222222';
export const SYNTHETIC_CONTRACT = 'synthetic.handover.test';

/** A wire-format signed transaction for `nonce`, with tx_hash computed from the raw bytes. */
export function syntheticTx(
  nonce: number,
  overrides: Partial<SignedTxView> = {},
  key: Hex = TEST_KEY,
): SignedTxView {
  const raw = signedTxWithKey(key, nonce, { to: SYNTHETIC_RECIPIENT });
  return {
    nonce,
    to: SYNTHETIC_RECIPIENT,
    value_wei: (BigInt(nonce + 1) * 10n ** 15n).toString(),
    gas_limit: '21000',
    max_fee_per_gas: '3000000000',
    max_priority_fee_per_gas: '1000000000',
    tx_hash: txHashOf(raw),
    raw_signed_tx_hex: raw,
    signed_at_ns: `${nonce + 1}000000000`,
    ...overrides,
  };
}

export function syntheticWallet(nextNonce: number, inFlight = false, sigCount = nextNonce): WalletView {
  return {
    token_id: '0',
    owner_id: 'synthetic-owner.test',
    path: 'handover-0',
    next_nonce: nextNonce,
    in_flight: inFlight,
    listing: null,
    sig_count: sigCount,
    minted_at_ns: '1000000000',
  };
}

export function syntheticSnapshot(params: {
  nextNonce: number;
  inFlight?: boolean;
  sigLog: SignedTxView[];
  confirmedNonce: number;
  pendingNonce?: number;
  expect?: Verdict;
  balanceWei?: string;
  note?: string;
}): Snapshot {
  const snap: Snapshot = {
    kind: 'handover-snapshot',
    version: 1,
    synthetic: true,
    note: params.note ?? SYNTHETIC_NOTE,
    capturedAt: '1970-01-01T00:00:00.000Z',
    contractId: SYNTHETIC_CONTRACT,
    tokenId: '0',
    address: SYNTHETIC_ADDRESS,
    wallet: syntheticWallet(params.nextNonce, params.inFlight ?? false, params.sigLog.length),
    sigLog: params.sigLog,
    chain: {
      confirmedNonce: params.confirmedNonce,
      balanceWei: params.balanceWei ?? '1000000000000000000',
    },
  };
  if (params.pendingNonce !== undefined) snap.chain.pendingNonce = params.pendingNonce;
  if (params.expect !== undefined) snap.expect = params.expect;
  return snap;
}

/** A tx at `nonce` signed by a different throwaway key (0x...02): recovers to the wrong address. */
export function wrongSignerTx(nonce: number): SignedTxView {
  return syntheticTx(nonce, {}, OTHER_KEY);
}

export function range(from: number, to: number): number[] {
  const out: number[] = [];
  for (let n = from; n < to; n++) out.push(n);
  return out;
}
